edits.before:
// Esc
case 27:
  // Clear "input" value
  ctx.input.value = "";

  /**
   * @emit {clear} event on input clear
   **/
  eventEmitter('clear', ctx);

  close(ctx);
  break;

edits.after:
// Esc
case 27:

  /**
   * @emit {clear} event on input clear
   **/
  eventEmitter('clear', ctx);

  close(ctx);
  break;
